(function () {
  'use strict';

  window.initVisionSimulator = function initVisionSimulator() {
    var container = document.getElementById('vision-simulator-container');
    if (!container) return;

    var sphere = -2.00;
    var cylinder = 0.00;
    var axis = 0;
    var splitPos = 0.5;

    container.innerHTML = `
      <div class="sim-wrapper">
        <div class="sim-header">
          <span class="sim-badge">Interactive Optical Lab</span>
          <h3 class="sim-title">Interactive LASIK Simulator</h3>
          <p class="sim-subtitle">Slide the split-divider or select condition presets to simulate your optical focus before vs. after Custom Wavefront LASIK.</p>
        </div>

        <div class="sim-stage-container" id="sim-stage">
          <canvas id="vision-sim-canvas-post" class="sim-canvas"></canvas>
          <canvas id="vision-sim-canvas-pre" class="sim-canvas sim-canvas-clipped"></canvas>

          <div class="sim-overlay-badge sim-badge-left" id="sim-badge-pre">
            <span class="sim-status-dot dot-red"></span> PRE: <span id="sim-telemetry-pre">-2.00D <span class="sim-badge-subtext">(Mild Nearsighted)</span></span>
          </div>

          <div class="sim-overlay-badge sim-badge-right" id="sim-badge-post">
            <span class="sim-status-dot dot-cyan"></span> POST: CustomVue® HD (20/20 or Better)
          </div>
          
          <div class="sim-split-divider" id="sim-divider" style="left: 50%;">
            <div class="sim-handle" role="slider" tabindex="0" aria-valuemin="0" aria-valuemax="100" aria-valuenow="50" aria-label="Drag to compare pre and post LASIK vision">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M18 8L22 12L18 16M6 8L2 12L6 16"/></svg>
            </div>
          </div>
        </div>

        <!-- Horizontal Scroll / Swipe Presets Bar -->
        <div class="sim-presets-grid" role="group" aria-label="Vision Condition Presets">
          <button type="button" class="sim-preset-btn active" data-sphere="-2.00" data-cyl="0" data-axis="0">Mild Nearsighted (-2.00 D)</button>
          <button type="button" class="sim-preset-btn" data-sphere="-6.00" data-cyl="0" data-axis="0">High Nearsighted (-6.00 D)</button>
          <button type="button" class="sim-preset-btn" data-sphere="0" data-cyl="-2.50" data-axis="90">Astigmatism (-2.50 D @ 90°)</button>
          <button type="button" class="sim-preset-btn" data-sphere="3.00" data-cyl="0" data-axis="0">Farsightedness (+3.00 D)</button>
          <button type="button" class="sim-preset-btn sim-preset-2020" id="sim-preset-2020" data-sphere="0" data-cyl="0" data-axis="0">Standard 20/20 (Night Glare)</button>
          <button type="button" class="sim-preset-btn sim-preset-hd" id="sim-preset-hd">✨ CustomVue® HD Clarity</button>
        </div>

        <!-- 20/20 vs CustomVue HD Comparison Explainer Banner -->
        <div class="sim-comparison-explainer" id="sim-explainer">
          <div class="sim-explainer-col item-2020">
            <div class="sim-explainer-tag"><span class="sim-status-dot dot-amber"></span> Standard 20/20 Sight</div>
            <p class="sim-explainer-text">Corrects basic sphere &amp; astigmatism, but leaves natural <strong>Higher-Order Aberrations (HOAs)</strong>, which cause night driving halos, headlight glare spikes, and softer edge contrast.</p>
          </div>
          <div class="sim-explainer-divider">
            <span class="sim-vs-pill">VS</span>
          </div>
          <div class="sim-explainer-col item-2015">
            <div class="sim-explainer-tag"><span class="sim-status-dot dot-cyan"></span> CustomVue® Wavefront HD</div>
            <p class="sim-explainer-text">3D WaveScan wavefront maps 250+ individual corneal micro-contours, <strong>neutralizing HOAs</strong> for crisper edge contrast, minimized night glare, and sharper detail (with 20/15 clarity achievable as an optimal goal for eligible eyes).</p>
          </div>
        </div>
        <p class="sim-clinical-disclaimer" style="font-size:0.75rem; color:#94a3b8; text-align:center; margin:14px auto 0; max-width:760px; line-height:1.5;">*Disclaimer: Visual simulation for educational purposes only. Individual visual outcomes vary. Over 98% of patients achieve 20/20 or better; while 20/15 vision is an aspirational clinical goal, it cannot be guaranteed for every patient.</p>

              </div>
    `;

    var canvasPre = document.getElementById('vision-sim-canvas-pre');
    var canvasPost = document.getElementById('vision-sim-canvas-post');
    var ctxPre = canvasPre.getContext('2d');
    var ctxPost = canvasPost.getContext('2d');
    var stage = document.getElementById('sim-stage');
    var divider = document.getElementById('sim-divider');

    // High-Resolution 4K HD Night Driving Asset (Optimized WebP with PNG fallback)
    var bgImg = new Image();
    bgImg.src = './assets/hd_night_highway_scene.webp?v=6';
    bgImg.onerror = function() {
      if (bgImg.src.indexOf('.webp') !== -1) {
        bgImg.src = './assets/hd_night_highway_scene.png?v=5';
      }
    };

    // Pre-computed native resolution specular light map for authentic Higher-Order Aberration halos
    var lightMapCanvas = null;
    function buildLightMap() {
      if (!bgImg || !bgImg.naturalWidth) return;
      lightMapCanvas = document.createElement('canvas');
      var nw = bgImg.naturalWidth;
      var nh = bgImg.naturalHeight;
      lightMapCanvas.width = nw;
      lightMapCanvas.height = nh;
      var lCtx = lightMapCanvas.getContext('2d');
      lCtx.drawImage(bgImg, 0, 0);
      try {
        var imgData = lCtx.getImageData(0, 0, nw, nh);
        var d = imgData.data;
        for (var i = 0; i < d.length; i += 4) {
          var r = d[i], g = d[i+1], b = d[i+2];
          var lum = 0.299 * r + 0.587 * g + 0.114 * b;
          // Strictly isolate bright point lights (taillights, headlights, streetlights, illuminated sign letters)
          if (lum < 155) {
            d[i+3] = 0;
          } else {
            var factor = Math.min(1, (lum - 155) / 65);
            d[i+3] = Math.round(factor * 255);
          }
        }
        lCtx.putImageData(imgData, 0, 0);
      } catch (err) {
        lightMapCanvas = null;
      }
    }

    var imgLoaded = false;
    bgImg.onload = function () {
      imgLoaded = true;
      buildLightMap();
      updateSimulation();
    };

    var simVisible = false;
    var simObserver = ('IntersectionObserver' in window) ? new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        simVisible = entry.isIntersecting;
        if (simVisible) {
          updateSimulation();
        }
      });
    }, { rootMargin: '200px' }) : null;

    // Aspect-ratio preserving Cover Math to prevent stretching/distortion
    function drawImageCover(ctx, img, width, height) {
      var imgW = img.naturalWidth || img.width || 1920;
      var imgH = img.naturalHeight || img.height || 1080;
      var imgRatio = imgW / imgH;
      var targetRatio = width / height;
      var renderW, renderH, offsetX, offsetY;

      if (targetRatio > imgRatio) {
        renderW = width;
        renderH = width / imgRatio;
        offsetX = 0;
        offsetY = (height - renderH) / 2;
      } else {
        renderH = height;
        renderW = height * imgRatio;
        offsetX = (width - renderW) / 2;
        offsetY = 0;
      }
      ctx.drawImage(img, offsetX, offsetY, renderW, renderH);
    }

    function updateSimulation() {
      if (!stage) return;
      var cssW = stage.clientWidth || 800;
      var cssH = stage.clientHeight || 380;
      var dpr = Math.max(2, window.devicePixelRatio || 1);

      // High-DPI Retina resolution canvas scaling to eliminate blurriness
      canvasPre.width = canvasPost.width = Math.round(cssW * dpr);
      canvasPre.height = canvasPost.height = Math.round(cssH * dpr);

      ctxPost.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctxPre.setTransform(dpr, 0, 0, dpr, 0, 0);
      
      // Set high-quality image smoothing
      ctxPost.imageSmoothingEnabled = true;
      ctxPost.imageSmoothingQuality = 'high';
      ctxPre.imageSmoothingEnabled = true;
      ctxPre.imageSmoothingQuality = 'high';

      if (!imgLoaded) {
        ctxPost.fillStyle = '#060b18';
        ctxPost.fillRect(0, 0, cssW, cssH);
        ctxPost.fillStyle = '#e2b857';
        ctxPost.font = '700 13px "Plus Jakarta Sans", sans-serif';
        ctxPost.fillText('Loading 4K HD Scene...', cssW / 2 - 70, cssH / 2);
        return;
      }

      // 1. Post-LASIK HD 20/15 Canvas (CustomVue Wavefront Guided Acuity)
      ctxPost.clearRect(0, 0, cssW, cssH);
      ctxPost.save();
      // Wavefront 20/15 HD: Razor-sharp contrast, punchy blacks, zero halos
      ctxPost.filter = 'contrast(1.10) brightness(1.02) saturate(1.06)';
      drawImageCover(ctxPost, bgImg, cssW, cssH);
      ctxPost.restore();

      // 2. Pre-LASIK / Standard 20/20 Canvas Physics
      var absSphere = Math.abs(sphere);
      var absCyl = Math.abs(cylinder);
      var isStandard2020 = (absSphere === 0 && absCyl === 0);

      ctxPre.clearRect(0, 0, cssW, cssH);
      ctxPre.save();

      if (isStandard2020) {
        // STANDARD 20/20 VISION:
        // Eye lacks custom wavefront optimization: suffers from natural Higher-Order Aberrations (HOAs)
        // 1) Base scene has subtle optical softening & lower MTF contrast sensitivity
        ctxPre.filter = 'contrast(0.94) brightness(0.97) blur(0.35px)';
        drawImageCover(ctxPre, bgImg, cssW, cssH);
        ctxPre.restore();

        // 2) Spherical aberration halos and coma glare bloom around night headlights & signs
        if (lightMapCanvas) {
          ctxPre.save();
          ctxPre.globalCompositeOperation = 'screen';

          // Spherical aberration halo ring (medium radius)
          ctxPre.filter = 'blur(15px) brightness(1.35)';
          ctxPre.globalAlpha = 0.75;
          drawImageCover(ctxPre, lightMapCanvas, cssW, cssH);

          // Specular core light flare
          ctxPre.filter = 'blur(5px) brightness(1.60)';
          ctxPre.globalAlpha = 0.60;
          drawImageCover(ctxPre, lightMapCanvas, cssW, cssH);

          // Wide night scatter / veiling glare
          ctxPre.filter = 'blur(28px) brightness(1.20)';
          ctxPre.globalAlpha = 0.40;
          drawImageCover(ctxPre, lightMapCanvas, cssW, cssH);

          ctxPre.restore();
        }
      } else {
        // UNCORRECTED REFRACTIVE ERROR (Myopia, Hyperopia, Astigmatism)
        var blurPx = (absSphere * 2.2) + (absCyl * 1.2);
        var rad = (axis - 90) * Math.PI / 180;
        var scaleX = 1 + (absCyl * 0.05 * Math.abs(Math.cos(rad)));
        var scaleY = 1 + (absCyl * 0.05 * Math.abs(Math.sin(rad)));

        ctxPre.filter = 'blur(' + blurPx.toFixed(1) + 'px) contrast(' + Math.max(0.75, 1 - (blurPx * 0.02)).toFixed(2) + ')';
        ctxPre.translate(cssW / 2, cssH / 2);
        ctxPre.rotate(rad);
        ctxPre.scale(scaleX, scaleY);
        ctxPre.rotate(-rad);
        ctxPre.translate(-cssW / 2, -cssH / 2);

        drawImageCover(ctxPre, bgImg, cssW, cssH);
        ctxPre.restore();

        // Refractive night flare and smeared blur bloom
        if (lightMapCanvas && blurPx > 0.4) {
          ctxPre.save();
          ctxPre.globalCompositeOperation = 'screen';
          var myopicBloom = Math.min(36, 12 + blurPx * 2.5);
          ctxPre.filter = 'blur(' + myopicBloom.toFixed(1) + 'px) brightness(1.25)';
          ctxPre.globalAlpha = Math.min(0.65, 0.35 + (blurPx * 0.04));
          drawImageCover(ctxPre, lightMapCanvas, cssW, cssH);
          ctxPre.restore();
        }
      }

      // Clip Path position adjustment
      var clipW = cssW * splitPos;
      canvasPre.style.clipPath = 'polygon(0 0, ' + clipW + 'px 0, ' + clipW + 'px 100%, 0 100%)';
      divider.style.left = clipW + 'px';

      // Telemetry readout update
      var telemetryPre = document.getElementById('sim-telemetry-pre');
      var badgePreDot = document.querySelector('#sim-badge-pre .sim-status-dot');
      if (telemetryPre) {
        if (isStandard2020) {
          telemetryPre.innerHTML = 'Standard 20/20 <span class="sim-badge-subtext">(Night Glare &amp; Halos)</span>';
          telemetryPre.style.color = '#fbbf24';
          if (badgePreDot) {
            badgePreDot.className = 'sim-status-dot dot-amber';
          }
        } else {
          var sphStr = (sphere > 0 ? '+' : '') + sphere.toFixed(2) + 'D';
          var cylStr = cylinder < 0 ? ' / ' + cylinder.toFixed(2) + 'D @ ' + axis + '°' : '';
          telemetryPre.textContent = sphStr + cylStr;
          telemetryPre.style.color = '#ef4444';
          if (badgePreDot) {
            badgePreDot.className = 'sim-status-dot dot-red';
          }
        }
      }
    }

    // Smooth split divider animation helper
    var animFrameId = null;
    function animateSplitTo(targetPos) {
      if (animFrameId) cancelAnimationFrame(animFrameId);
      var startPos = splitPos;
      var startTime = null;
      var duration = 400;
      function step(timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / duration, 1);
        var ease = 1 - Math.pow(1 - progress, 3);
        splitPos = startPos + (targetPos - startPos) * ease;
        updateSimulation();
        if (progress < 1) {
          animFrameId = requestAnimationFrame(step);
        } else {
          animFrameId = null;
        }
      }
      animFrameId = requestAnimationFrame(step);
    }

    // Split Handle Drag Controls
    var isDragging = false;
    function setSplitFromMouse(e) {
      if (animFrameId) {
        cancelAnimationFrame(animFrameId);
        animFrameId = null;
      }
      var rect = stage.getBoundingClientRect();
      var pageX = (e.touches && e.touches[0]) ? e.touches[0].clientX : e.clientX;
      if (typeof pageX !== 'number') return;
      var x = pageX - rect.left;
      splitPos = Math.max(0.02, Math.min(0.98, x / rect.width));
      updateSimulation();
    }

    stage.addEventListener('mousedown', function (e) { isDragging = true; setSplitFromMouse(e); });
    stage.addEventListener('touchstart', function (e) { isDragging = true; setSplitFromMouse(e); }, { passive: true });
    window.addEventListener('mousemove', function (e) { if (isDragging) setSplitFromMouse(e); });
    window.addEventListener('touchmove', function (e) { if (isDragging) setSplitFromMouse(e); }, { passive: true });
    window.addEventListener('mouseup', function () { isDragging = false; });
    window.addEventListener('touchend', function () { isDragging = false; });

    // Presets Click Handler
    var presetBtns = container.querySelectorAll('.sim-preset-btn');
    presetBtns.forEach(function (btn) {
      btn.addEventListener('click', function () {
        presetBtns.forEach(function (b) { b.classList.remove('active'); });
        btn.classList.add('active');

        if (btn.id === 'sim-preset-hd') {
          sphere = 0;
          cylinder = 0;
          axis = 0;
          animateSplitTo(0.04);
        } else if (btn.id === 'sim-preset-2020') {
          sphere = 0;
          cylinder = 0;
          axis = 0;
          animateSplitTo(0.5);
        } else {
          var sph = parseFloat(btn.getAttribute('data-sphere')) || 0;
          var cyl = parseFloat(btn.getAttribute('data-cyl')) || 0;
          var ax = parseInt(btn.getAttribute('data-axis'), 10) || 0;
          sphere = sph;
          cylinder = cyl;
          axis = ax;
          if (splitPos < 0.2 || splitPos > 0.8) {
            animateSplitTo(0.5);
          }
        }
        updateSimulation();
      });
    });

    window.addEventListener('resize', function() {
      if (simVisible) updateSimulation();
    }, { passive: true });

    if (simObserver && stage) {
      simObserver.observe(stage);
    } else {
      setTimeout(updateSimulation, 500);
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', window.initVisionSimulator);
  } else {
    window.initVisionSimulator();
  }
})();
